  "sig.copyFail":   { en: "This browser did not allow copying — use Download, or select the signature above and copy it.", zh: "此浏览器不允许复制 — 请使用下载，或选中上方签名后复制。", ar: "المتصفح ما سمحش بالنسخ — نزّل الملف، أو حدّد التوقيع اللي فوق وانسخه." },
  "sig.copyHint":   { en: "The logo loads from hub.koleexgroup.com, so it shows in China too. Make the signature again when your title or number changes.", zh: "标志从 hub.koleexgroup.com 加载，在中国也能显示。职位或号码变化时请重新制作签名。", ar: "اللوجو بيتحمّل من hub.koleexgroup.com فبيظهر في الصين كمان. اعمل التوقيع تاني لما المسمى أو الرقم يتغير." },
  "sig.how": { en: "How to add it to your mail", zh: "如何添加到邮箱", ar: "إزاي تضيفه للإيميل" },
  "sig.how.gmail":        { en: "Gmail", zh: "Gmail", ar: "Gmail" },
  "sig.how.gmail.steps":  { en: "Settings → See all settings → Signature → Create new → paste → Save changes (at the bottom).", zh: "设置 → 查看所有设置 → 签名 → 新建 → 粘贴 → 保存更改（页面底部）。", ar: "الإعدادات ← كل الإعدادات ← التوقيع ← جديد ← الزق ← احفظ التغييرات (تحت خالص)." },
  "sig.how.outlook":       { en: "Outlook (web and new Outlook)", zh: "Outlook（网页版和新版）", ar: "Outlook (الويب والجديد)" },
  "sig.how.outlook.steps": { en: "Settings → Accounts → Signatures → New signature → paste → Save; pick it for new mails and for replies.", zh: "设置 → 帐户 → 签名 → 新建签名 → 粘贴 → 保存；分别选择新邮件和回复使用的签名。", ar: "الإعدادات ← الحسابات ← التوقيعات ← توقيع جديد ← الزق ← احفظ؛ واختاره للإيميلات الجديدة وللردود." },
  "sig.how.outlookWin":       { en: "Outlook for Windows (classic)", zh: "Windows 版 Outlook（经典）", ar: "Outlook ويندوز (القديم)" },
  "sig.how.outlookWin.steps": { en: "File → Options → Mail → Signatures → New → paste into the box → OK.", zh: "文件 → 选项 → 邮件 → 签名 → 新建 → 粘贴到编辑框 → 确定。", ar: "ملف ← خيارات ← البريد ← التوقيعات ← جديد ← الزق في المربع ← موافق." },
  "sig.how.apple":        { en: "Apple Mail (Mac)", zh: "Apple 邮件（Mac）", ar: "Apple Mail (ماك)" },
  "sig.how.apple.steps":  { en: "Mail → Settings → Signatures → + → paste; untick \"Always match my default message font\".", zh: "邮件 → 设置 → 签名 → + → 粘贴；取消勾选“始终匹配我的默认信息字体”。", ar: "Mail ← الإعدادات ← التوقيعات ← + ← الزق؛ وشيل علامة \"مطابقة خط الرسائل الافتراضي دايمًا\"." },
  "sig.how.iphone":       { en: "iPhone Mail", zh: "iPhone 邮件", ar: "إيميل الآيفون" },
  "sig.how.iphone.steps": { en: "Settings → Apps → Mail → Signature → paste the reply version (the iPhone keeps text, not the logo).", zh: "设置 → App → 邮件 → 签名 → 粘贴回复版（iPhone 只保留文字，不保留标志）。", ar: "الإعدادات ← التطبيقات ← Mail ← التوقيع ← الزق نسخة الردود (الآيفون بيحتفظ بالكلام من غير اللوجو)." },
  "sig.how.foxmail":       { en: "Foxmail, QQ Mail, NetEase", zh: "Foxmail、QQ 邮箱、网易邮箱", ar: "Foxmail وQQ Mail وNetEase" },
  "sig.how.foxmail.steps": { en: "Settings → Signature → New → paste (or choose HTML and paste the code).", zh: "设置 → 签名 → 新建 → 粘贴（或选择 HTML 后粘贴代码）。", ar: "الإعدادات ← التوقيع ← جديد ← الزق (أو اختار HTML والزق الكود)." },
  "sig.code": { en: "HTML code", zh: "HTML 代码", ar: "كود HTML" },
  "sig.spec.content": { en: "The book (ch. 93): name, title, logo, one phone, one email, the website. The only extras: a portrait and, while there is an event, one banner — no quotes, social icon rows or animated pictures.", zh: "品牌手册（第 93 章）：姓名、职位、标志、一个电话、一个邮箱、网站。唯一的附加：肖像，以及活动期间的一个横幅 — 不加名言、社交图标或动图。", ar: "الكتاب (فصل 93): الاسم، المسمى، اللوجو، تليفون واحد، إيميل واحد، الموقع. الإضافات الوحيدة: صورة شخصية، وبانر واحد وقت المعرض — من غير حكم ولا أيقونات سوشيال ولا صور متحركة." },
  "sig.spec.fonts":   { en: "Fonts every computer has: Arial / Helvetica, Tahoma for Arabic, PingFang / Microsoft YaHei for Chinese — mail apps do not load Inter.", zh: "使用所有电脑都有的字体：Arial / Helvetica，阿拉伯文用 Tahoma，中文用苹方 / 微软雅黑 — 邮箱不加载 Inter。", ar: "خطوط موجودة على أي كمبيوتر: Arial / Helvetica، وTahoma للعربي، وPingFang / Microsoft YaHei للصيني — برامج الإيميل ما بتحمّلش Inter." },
  "sig.spec.logo":    { en: "The logo is a picture on its own tile, at least 100 px wide (the screen minimum), loaded from our own domain.", zh: "标志为带底块的图片，宽度至少 100 像素（屏幕最小尺寸），从公司域名加载。", ar: "اللوجو صورة على خلفيتها، عرضها 100 بكسل على الأقل (أقل مقاس للشاشة)، بتتحمّل من الدومين بتاعنا." },
  "sig.spec.group":   { en: "The group lockup needs the logo at 160 px or wider (ch. 43) — it grows to 160 px here.", zh: "集团组合要求标志至少 160 像素（第 43 章）— 此处自动放大到 160 像素。", ar: "شكل المجموعة محتاج اللوجو 160 بكسل أو أكتر (فصل 43) — فهنا بيكبر لـ 160." },
  "sig.spec.black":   { en: "Black: the team card's colours. In a mail app's dark mode it stays black; in some apps it turns light grey — the logo tile keeps it readable.", zh: "黑色：团队名片的配色。在深色模式中保持黑色；部分应用会变为浅灰 — 标志底块保证清晰。", ar: "الأسود: ألوان كارت الفريق. في الوضع الغامق بيفضل أسود؛ وفي شوية برامج بيقلب رمادي فاتح — وخلفية اللوجو بتخليه يتقري." },
  "sig.spec.banner":  { en: "The banner only from the day the event is announced to its last day — then turn it off. One banner at most.", zh: "横幅只在活动公布之日至最后一天使用 — 之后关闭。最多一个横幅。", ar: "البانر بس من يوم إعلان المعرض لآخر يوم فيه — وبعدين اقفله. بانر واحد بس." },
  "sig.spec.reply":   { en: "Replies and forwards use the short version: name, title, phone.", zh: "回复和转发使用简短版：姓名、职位、电话。", ar: "الردود والتحويل بالنسخة المختصرة: الاسم، المسمى، التليفون." },

