  "tpl.f.bigText":     { en: "Large line on the back", zh: "背面大字", ar: "السطر الكبير على الضهر" },
  "tpl.f.bigTextHint": { en: "Set very large up the card, running off the top as in the reference — the tagline by default (ch. 20).", zh: "竖向超大排列，像参考设计一样超出顶部 — 默认为品牌口号（第 20 章）。", ar: "بيتكتب كبير جداً بالطول ويطلع برّه الكارت من فوق زي الريفرنس — الشعار هو الافتراضي (فصل 20)." },
  "spec.idCard":     { en: "Card: PVC 0.76 mm (CR80) or 600–700 g/m² board, full colour to the edges.", zh: "卡片：PVC 0.76 毫米（CR80）或 600–700 克卡纸，全彩满版印刷。", ar: "الكارت: PVC 0.76 مم (CR80) أو كرتون 600–700 جرام/م²، ألوان كاملة لحد الحواف." },
  "spec.idRound":    { en: "Corners: round, 3.2 mm radius (the CR80 standard).", zh: "圆角：半径 3.2 毫米（CR80 标准）。", ar: "الحواف: مدورة، نص قطر 3.2 مم (مقاس CR80)." },
  "spec.idSlot":     { en: "Slot punch at the top centre (the size is on the die line).", zh: "顶部居中打长条孔（尺寸见模切线）。", ar: "فتحة شريط طولية في نص الكارت من فوق (المقاس على خط القص)." },
  "spec.idHole":     { en: "A round hole at the top centre for the clip (the size is on the die line).", zh: "顶部居中打圆孔用于挂扣（尺寸见模切线）。", ar: "فتحة مدورة في نص الكارت من فوق للكلبس (المقاس على خط القص)." },
  "spec.idBarcode":  { en: "The barcode is the staff number in Code 128 — scan one printed badge before printing the series.", zh: "条码为 Code 128 员工编号 — 批量印刷前先扫描一张样卡。", ar: "الباركود هو رقم الموظف بكود 128 — اعمل سكان لكارت مطبوع قبل ما تطبع الباقي." },
  "spec.idGradient": { en: "The colour panel prints in four colours (CMYK) — purple and blue as in the reference (owner's choice); ask for a printed proof.", zh: "色块以四色（CMYK）印刷 — 紫色与蓝色按参考设计（所有者决定）；请要求打样。", ar: "لوحة الألوان بتتطبع 4 ألوان (CMYK) — البنفسجي والأزرق زي الريفرنس (اختيار صاحب الشركة)؛ اطلب بروفة مطبوعة." },
  "spec.idDots":     { en: "The dots print white on black (front) and light grey on grey (back).", zh: "圆点正面为黑底白色，背面为灰底浅灰。", ar: "النقط بتتطبع أبيض على أسود (الوش) ورمادي فاتح على رمادي (الضهر)." },
  "tpl.f.descriptorOn":   { en: "Show the descriptor", zh: "显示品牌描述语", ar: "اظهر وصف الشركة" },
  "tpl.f.descriptor":     { en: "Descriptor", zh: "品牌描述语", ar: "وصف الشركة" },
  "tpl.f.descriptorHint": { en: "The brand book's three words (ch. 21), in the card's language — they sit by the logo where the reference had its own words.", zh: "品牌手册的三个词（第 21 章），随名片语言 — 放在参考设计原有文字的位置、标志旁边。", ar: "التلات كلمات بتوع كتاب البراند (فصل 21) بلغة الكارت — مكانهم جنب اللوجو مكان كلام الريفرنس." },
  "spec.rMetal":     { en: "Metal: 0.8 mm black stainless steel, the logo and the text laser-etched, the pattern etched gloss. On board: black soft-touch, the pattern in raised gloss spot UV, the logo in white foil.", zh: "金属：0.8 毫米黑色不锈钢，标志与文字激光蚀刻，图案蚀刻亮面。纸卡：黑色触感膜，图案用凸起亮光局部 UV，标志白色烫印。", ar: "معدن: ستانلس أسود 0.8 مم، اللوجو والكلام محفورين ليزر، والنقشة محفورة لامعة. على كرتون: أسود سوفت تاتش، النقشة يو في لامع بارز، واللوجو فويل أبيض." },
  "spec.round3":     { en: "Corners: round, 3 mm radius (die-cut).", zh: "圆角：半径 3 毫米（模切）。", ar: "الحواف: مدورة، نص قطر 3 مم (قص بالفورمة)." },
  "spec.round4":     { en: "Corners: round, 4 mm radius (die-cut).", zh: "圆角：半径 4 毫米（模切）。", ar: "الحواف: مدورة، نص قطر 4 مم (قص بالفورمة)." },
  "spec.round5":     { en: "Corners: round, 5 mm radius (die-cut).", zh: "圆角：半径 5 毫米（模切）。", ar: "الحواف: مدورة، نص قطر 5 مم (قص بالفورمة)." },
  "spec.rNotch":     { en: "A triangle hole in the top corner, 4.2 mm, 2 mm from the edges — laser-cut on metal, die-cut on board.", zh: "上角三角形孔，4.2 毫米，距边 2 毫米 — 金属激光切割，纸卡模切。", ar: "فتحة مثلث في الركن اللي فوق، 4.2 مم وبعيدة 2 مم عن الحرف — ليزر على المعدن وفورمة على الكرتون." },
  "spec.rGlow":      { en: "The blue light prints in four colours (CMYK) over rich black; ask for a printed proof — a screen shows it brighter. Blue as in the reference (owner's choice).", zh: "蓝光以四色（CMYK）印在四色黑上；请要求打样 — 屏幕显示更亮。蓝色按参考设计（所有者决定）。", ar: "النور الأزرق بيتطبع 4 ألوان (CMYK) على أسود غني؛ اطلب بروفة مطبوعة — الشاشة بتبينه أفتح. الأزرق زي الريفرنس (اختيار صاحب الشركة)." },
  "spec.rFrame":     { en: "The frame is a 0.4 mm white line; it stops on both sides of the title.", zh: "线框为 0.4 毫米白线，在职位两侧断开。", ar: "البرواز خط أبيض 0.4 مم، وبيقف على الناحيتين من المسمى." },
  "spec.rWorld":     { en: "The world map is the KOLEEX dotted map (brand book ch. 57), dark grey on black.", zh: "世界地图为 KOLEEX 点阵地图（品牌手册第 57 章），黑底深灰。", ar: "خريطة العالم هي خريطة نقط KOLEEX (كتاب البراند فصل 57)، رمادي غامق على أسود." },
  "spec.rBlackBoth": { en: "Both sides: white print on black board.", zh: "双面：黑卡上白色印刷。", ar: "الوشين: طباعة بيضا على كرتون أسود." },
  "spec.rRim":       { en: "The white rim (front) and the black rim (back) print to the trim — ask for a tight cut, ±0.3 mm.", zh: "正面白边与背面黑边印至裁切线 — 请要求精确裁切，±0.3 毫米。", ar: "الإطار الأبيض (الوش) والأسود (الضهر) بيتطبعوا لحد خط القص — اطلب قص دقيق ±0.3 مم." },
  "spec.rPaper":     { en: "Front: black to the edges. Back: white uncoated cotton board, 600 g/m², black print.", zh: "正面：黑色满版。背面：白色无涂布棉纸卡，600 克/平方米，黑色印刷。", ar: "الوش: أسود لحد الحواف. الضهر: كرتون قطن أبيض غير مغطى 600 جرام/م²، طباعة سودا." },
  "spec.rGhost":     { en: "Front: the rings in dark grey on black. Back: the circle a 7 % grey tint, the logo in it white.", zh: "正面：黑底深灰圆弧。背面：圆为 7% 灰，内部标志为白色。", ar: "الوش: الحلقات رمادي غامق على أسود. الضهر: الدايرة رمادي 7٪ واللوجو جواها أبيض." },

