  "evp.spec.photo": { en: "Photo posts: the same preset for the whole series, no close-up faces without consent.", zh: "照片帖：整个系列用同一调色，未经同意不拍特写人脸。", ar: "بوستات الصور: نفس الفلتر للسلسلة كلها، ومن غير وشوش قريبة من غير إذن." },
  "evp.spec.dates": { en: "Dates as DD/MM/YYYY; the booth is announced 8 weeks before, \"Meet us at\" 4 weeks before (ch. 116).", zh: "日期写作 日/月/年；提前 8 周公布展位，提前 4 周发布“与您相见”（第 116 章）。", ar: "التواريخ يوم/شهر/سنة؛ الجناح يتعلن قبلها بـ8 أسابيع، و«قابلنا في» قبلها بـ4 (فصل 116)." },
  "evp.spec.eventLogo": { en: "The KOLEEX logo is never changed for an event; event colours stay inside black, white and silver.", zh: "KOLEEX 标志不因活动改变；活动颜色只在黑白银范围内。", ar: "لوجو KOLEEX عمره ما يتغير عشان إيفنت؛ وألوان الإيفنت جوه الأسود والأبيض والفضي." },
  "evp.spec.rhythm": { en: "During a fair: one photo and one short video a day; after it, a thank-you with our own photos.", zh: "展会期间：每天一张照片和一个短视频；展后用我们自己的照片致谢。", ar: "أثناء المعرض: صورة وفيديو قصير كل يوم؛ وبعده بوست شكر بصورنا." },
  "evp.needEvent": { en: "Write the event's name first.", zh: "请先填写活动名称。", ar: "اكتب اسم الإيفنت الأول." },

